import { NextResponse } from "next/server";
import { db } from "../../../../src/prisma/db";
import { GeminiAdapter } from "../../../../lib/providers/gemini";
import { GroqAdapter } from "../../../../lib/providers/groq";

interface RouteContext {
  params: Promise<{
    connectorId: string;
  }>;
}

function getApiKey(request: Request): string | null {
  const xApiKey = request.headers.get("x-api-key");

  if (xApiKey) {
    return xApiKey.trim();
  }

  const authorization = request.headers.get("authorization");

  if (authorization?.startsWith("Bearer ")) {
    return authorization.slice(7).trim();
  }

  return null;
}

export async function POST(
  request: Request,
  context: RouteContext
) {
  const startTime = Date.now();

  let connectorId: number | null = null;

  try {
    // Get connector ID from the URL
    const { connectorId: connectorIdParam } =
      await context.params;

    const id = Number(connectorIdParam);

    if (!Number.isInteger(id)) {
      return NextResponse.json(
        {
          success: false,
          error: "Invalid connector ID",
        },
        { status: 400 }
      );
    }

    connectorId = id;

    // Check the generated endpoint API key
    const configuredApiKey =
      process.env.AI_API_HUB_KEY;

    if (!configuredApiKey) {
      console.error(
        "AI_API_HUB_KEY is not configured"
      );

      return NextResponse.json(
        {
          success: false,
          error:
            "API authentication is not configured on the server.",
        },
        { status: 500 }
      );
    }

    const providedApiKey = getApiKey(request);

    if (
      !providedApiKey ||
      providedApiKey !== configuredApiKey
    ) {
      return NextResponse.json(
        {
          success: false,
          error: "Unauthorized. A valid API key is required.",
        },
        { status: 401 }
      );
    }

    // Read request body
    const body = await request.json();

    if (!body || body.input === undefined) {
      return NextResponse.json(
        {
          success: false,
          error: "Missing required field: input",
        },
        { status: 400 }
      );
    }

    // Get all connectors from the database
    const connectors =
      await db.orm.public.Connector.all();

    // Find the requested connector
    const connector = connectors.find(
      (item) => item.id === id
    );

    if (!connector) {
      return NextResponse.json(
        {
          success: false,
          error: "Connector not found",
        },
        { status: 404 }
      );
    }

    // Check if the connector is active
    if (!connector.isActive) {
      return NextResponse.json(
        {
          success: false,
          error:
            "This connector is currently disabled",
        },
        { status: 403 }
      );
    }

    // Validate Image Analyzer input
    const isVisionModel =
      connector.provider === "groq" &&
      connector.model === "qwen/qwen3.8-27b";

    if (isVisionModel) {
      if (
        !body.input ||
        typeof body.input !== "object" ||
        typeof body.input.imageData !== "string" ||
        !body.input.imageData
      ) {
        return NextResponse.json(
          {
            success: false,
            error:
              "Image data is required for the Image Analyzer.",
          },
          { status: 400 }
        );
      }
    }

    // Select the AI provider
    let adapter;

    if (connector.provider === "gemini") {
      adapter = new GeminiAdapter();
    } else if (connector.provider === "groq") {
      adapter = new GroqAdapter();
    } else {
      return NextResponse.json(
        {
          success: false,
          error: `Unsupported AI provider: ${connector.provider}`,
        },
        { status: 400 }
      );
    }

    // Call the AI provider
    const result = await adapter.generate({
      model: connector.model,
      prompt: connector.prompt,
      input: body.input,
      outputSchema: connector.outputSchema,
    });

    // Calculate response time
    const responseTime = Date.now() - startTime;

    // Save successful request
    await db.orm.public.ApiRequest.create({
      connectorId: connector.id,
      status: "success",
      responseTime,
      inputTokens: result.inputTokens,
      outputTokens: result.outputTokens,
    });

    // Return AI response
    return NextResponse.json({
      success: true,
      connector: connector.name,
      provider: connector.provider,
      model: connector.model,
      response: result.text,

      // Kept for compatibility with the existing response structure
      imageData: result.imageData ?? null,
      imageMimeType: result.imageMimeType ?? null,

      usage: {
        inputTokens: result.inputTokens,
        outputTokens: result.outputTokens,
        totalTokens: result.totalTokens,
      },

      responseTime,
    });
  } catch (error) {
    const responseTime = Date.now() - startTime;

    const errorMessage =
      error instanceof Error
        ? error.message
        : "AI provider request failed";

    console.error(
      "AI execution failed:",
      error
    );

    // Save failed AI/provider requests
    if (connectorId !== null) {
      try {
        await db.orm.public.ApiRequest.create({
          connectorId,
          status: "failed",
          responseTime,
          errorMessage,
        });
      } catch (loggingError) {
        console.error(
          "Failed to log failed API request:",
          loggingError
        );
      }
    }

    return NextResponse.json(
      {
        success: false,
        error: errorMessage,
        responseTime,
      },
      { status: 500 }
    );
  }
}
